293			t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
294		}
295	}
296	
297	// Results already written stay written when a later record fails, and no
298	// further records are processed.
299	func TestAggregatePartitionedOutputRetainedOnError(t *testing.T) {
300		input := strings.Join([]string{
