319			`{"type":"watermark","time":1000,"partition":0}`,
320			`{"type":"event","key":"k","time":1500,"value":1,"partition":1}`,
321		}, "\n")
322		stdout, _, err := runPartitioned(t, input, 1000, 2)
323		if err != nil {
324			t.Fatalf("unexpected error: %v", err)
