335			input     string
336			wantLine  int
337			wantInMsg string
338		}{
339			{"negative time", `{"type":"event","key":"k","time":-1,"value":1,"partition":0}` + "\n", 1, "non-negative"},
340			{"missing value", `{"type":"event","key":"k","time":1,"partition":0}` + "\n", 1, `"value"`},
341			{"empty key", `{"type":"event","key":"","time":1,"value":1,"partition":0}` + "\n", 1, "non-empty"},
342			{"watermark negative", `{"type":"watermark","time":-1,"partition":0}` + "\n", 1, "non-negative"},
