package edgefleet

import (
	"bytes"
	"fmt"
	"strings"
	"testing"
	"time"
)

// This file guards the cost of collecting physical lines, not their results.
// The result contract for long records split across arbitrary reads lives in
// aggregate_long_record_test.go and aggregate_chunked_input_test.go. What is
// pinned here is the complexity: when a legal record with a very long key
// arrives one or a few bytes per Read, line collection must cost about one
// newline scan per input byte -- linear in the cumulative input byte count
// and read count -- rather than one scan per Read over the whole accumulated
// tail, which is quadratic in the line length.

// singleByteCuts lists a cut before every byte except the first, the schedule
// that made the old rescanner quadratic.
func singleByteCuts(n int) []int {
	cuts := make([]int, 0, n-1)
	for at := 1; at < n; at++ {
		cuts = append(cuts, at)
	}
	return cuts
}

// bestSingleByteTime measures repeated one-byte-per-Read passes in growing
// batches until a batch spans at least minBatch, returning the best
// (minimum-noise) average per pass. Comparing two streams of the same byte
// length under the same schedule makes the ratio independent of the
// machine's absolute speed.
func bestSingleByteTime(t *testing.T, input string, minBatch time.Duration) time.Duration {
	t.Helper()
	cuts := singleByteCuts(len(input))
	iters := 1
	best := time.Duration(1<<63 - 1)
	for attempt := 0; attempt < 6; attempt++ {
		begin := time.Now()
		for i := 0; i < iters; i++ {
			var out, late bytes.Buffer
			if err := RunAggregate(newChunkReader(input, cuts...), 1000, &out, &late); err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
		}
		batch := time.Since(begin)
		if avg := batch / time.Duration(iters); avg < best {
			best = avg
		}
		if batch >= minBatch {
			return best
		}
		// Run long enough to rise above scheduler noise, then try again.
		iters *= 4
	}
	return best
}

// TestAggregateLineCollectionCostFollowsBytesNotLineLength is the complexity
// guard. Two inputs have essentially the SAME total byte count and arrive
// through the SAME number of one-byte Reads; they differ only in whether the
// bytes form one very long physical record or thousands of short ones. A
// linear collector scans every byte about once either way (plus read-call
// overhead, identical per byte), so the two timings are comparable. The old
// collector rescanned the whole pending tail after every Read, i.e. about
// L*L/2 comparisons for one L-byte line versus only N*m/2 for N bytes split
// into m-byte lines, making the long-line input hundreds of times slower
// despite the identical byte and read counts.
func TestAggregateLineCollectionCostFollowsBytesNotLineLength(t *testing.T) {
	if testing.Short() {
		t.Skip("timing guard skipped in -short mode")
	}
	const target = 200 * 1024

	// One long event record (long multibyte key) closed by a watermark.
	longKey := longKey(longKeySuffixA, target)
	oneLongLine := strings.Join([]string{
		fmt.Sprintf(`{"type":"event","key":%q,"time":100,"value":7}`, longKey),
		`{"type":"watermark","time":1000}`,
		``,
	}, "\n")

	// The same number of bytes as many short newline-terminated records, all
	// merging into one short-key window, closed by a watermark.
	shortRecord := `{"type":"event","key":"短","time":100,"value":1}` + "\n"
	var b strings.Builder
	for b.Len()+len(shortRecord) < target {
		b.WriteString(shortRecord)
	}
	b.WriteString(`{"type":"watermark","time":1000}` + "\n")
	manyShortLines := b.String()

	if len(oneLongLine) < target {
		t.Fatalf("test setup: long input is only %d bytes, want >= %d", len(oneLongLine), target)
	}
	// The two streams must be genuinely the same order of size; otherwise the
	// ratio would measure byte count rather than line layout.
	if got := len(oneLongLine); got > target*2 || got < target {
		t.Fatalf("test setup: long input %d bytes vs short input %d bytes", got, len(manyShortLines))
	}

	// The timed long-line delivery must also stay correct: the whole key
	// survives one-byte arrival and the watermark closes its window.
	var out, late bytes.Buffer
	if err := RunAggregate(newChunkReader(oneLongLine, singleByteCuts(len(oneLongLine))...), 1000, &out, &late); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	wantWindow := fmt.Sprintf(`{"key":%q,"start":0,"end":1000,"count":1,"sum":7}`+"\n", longKey)
	if out.String() != wantWindow {
		t.Fatalf("single-byte long-line output mismatch:\n got: %q\nwant: %q", out.String(), wantWindow)
	}
	if late.String() != "" {
		t.Fatalf("unexpected late notices: %q", late.String())
	}

	longAvg := bestSingleByteTime(t, oneLongLine, 30*time.Millisecond)
	shortAvg := bestSingleByteTime(t, manyShortLines, 30*time.Millisecond)

	// Linear collection: comparable cost for equal bytes and equal reads.
	// The short stream parses thousands of records (more callbacks), the long
	// stream copies/grows one large buffer (more copies), so either may win;
	// allow a generous factor either way. The quadratic rescanner made the
	// long stream hundreds of times slower.
	const factor = 6.0
	if ratio := float64(longAvg) / float64(shortAvg); ratio > factor {
		t.Fatalf("line collection cost grows with line length at fixed byte/read count: "+
			"one %d-byte line took %v/pass, %d bytes of short lines took %v/pass "+
			"(long/short ratio %.2f, want <= %.1f)",
			len(oneLongLine), longAvg, len(manyShortLines), shortAvg, ratio, factor)
	}
	// Absolute backstop: ~200 KiB delivered one byte at a time must finish
	// promptly with a linear collector, even on a slow, contended machine.
	if longAvg > 2*time.Second {
		t.Fatalf("single-byte processing of %d bytes took %v/pass, want under 2s", len(oneLongLine), longAvg)
	}
}

// TestAggregateLineCollectionAlternatingChunksLinear interleaves long and
// short records and alternates the read size between one byte and a few
// kilobytes, so the cursor that resumes the newline search must repeatedly
// skip already-searched long tails and then find newlines inside freshly
// appended bytes. Output must equal the one-shot reference; this guards
// correctness of the resume cursor under mixed chunking, the timing ratio is
// covered by the test above.
func TestAggregateLineCollectionAlternatingChunksLinear(t *testing.T) {
	keyA := longKey(longKeySuffixA, 64*1024)
	keyB := longKey(longKeySuffixB, 64*1024)
	lines := []string{
		``,
		fmt.Sprintf(`{"type":"event","key":%q,"time":100,"value":2}`, "短"),
		fmt.Sprintf(`{"type":"event","key":%q,"time":100,"value":10}`, keyA),
		`{"type":"watermark","time":500}`,
		fmt.Sprintf(`{"type":"event","key":%q,"time":100,"value":7}`, keyB),
		``,
		fmt.Sprintf(`{"type":"event","key":%q,"time":200,"value":4}`, "短"),
		`{"type":"watermark","time":1000}`,
	}
	input := strings.Join(lines, "\n") + "\n"

	var refOut, refLate bytes.Buffer
	if err := RunAggregate(strings.NewReader(input), 1000, &refOut, &refLate); err != nil {
		t.Fatalf("one-shot reference failed: %v", err)
	}

	// Alternating one-byte and 4 KiB cuts.
	var cuts []int
	pos := 0
	small := true
	for pos < len(input) {
		step := 1
		if !small {
			step = 4096
		}
		small = !small
		pos += step
		if pos < len(input) {
			cuts = append(cuts, pos)
		}
	}

	var out, late bytes.Buffer
	if err := RunAggregate(newChunkReader(input, cuts...), 1000, &out, &late); err != nil {
		t.Fatalf("alternating-chunk run failed: %v", err)
	}
	if out.String() != refOut.String() {
		t.Fatalf("alternating chunks changed the window output:\n got: %q\nwant: %q", out.String(), refOut.String())
	}
	if late.String() != refLate.String() {
		t.Fatalf("alternating chunks changed the late output:\n got: %q\nwant: %q", late.String(), refLate.String())
	}
}

package edgefleet

import (
	"encoding/json"
	"fmt"
	"strings"
	"testing"
)

// Regression safeguard for partition numbering as a mere source label.
//
// A partition number only identifies which independent input source a record
// came from; it must never enter the aggregate semantics: relabeling every
// partition number with a single bijection -- one that stays inside [0,N),
// neither merges two sources nor drops one, and is applied to EVERY record
// kind that carries a partition (events, watermarks and idle declarations) --
// must leave the window results byte-for-byte identical in content, row count
// and order, must leave every late notice identical in its event time, the
// watermark cited and the physical line number, and must keep a normal run
// successful. The only text allowed to change is the partition number named
// in an input error, which must be the relabeled number on the same physical
// line.
//
// The scenario is one business stream (window 1000, slide 600 -- 600 does not
// divide 1000) merged over THREE sources, one key "k", and the three sources
// play genuinely different roles that land on the zero, the maximum legal and
// a middle number:
//
//   - partition 0 (the zero index) is the source that races ahead;
//   - partition 2 (the maximum legal index for --partitions 3) is the source
//     that pins the overall effective watermark by lagging, then catches up;
//   - partition 1 (a middle index) is the source that goes idle and later
//     resumes with a legal watermark.
//
// The same key's events arrive from all three sources and, because the slide
// interval does not divide the window length, several of them land in more
// than one overlapping window. The stream first closes only the early window
// while the later overlapping window keeps receiving events. Source numbers
// never appear in the output. Everything goes through the public
// RunAggregatePartitionedSliding entry point; no production code, public entry
// point, result format or error convention is changed, and no renumbering
// command is introduced.

// partitionRenumberPermutation is the relabeling under test. It is a
// bijection of {0,1,2} onto itself that moves every role off its original
// number: the fast source 0 -> 2 (now the maximum legal index), the idle
// source 1 -> 0 (now the zero index), the limiter 2 -> 1 (now a middle
// index), so each of zero/max/middle is exercised by a different source than
// before, while the total partition count stays 3.
var partitionRenumberPermutation = map[int64]int64{0: 2, 1: 0, 2: 1}

// renumberFixtureSuccessLines is the shared 17-line stream. Partition numbers
// shown are the ORIGINAL labels; renumberPartitionFields applies the
// bijection. The blank-free layout keeps physical line numbers obvious.
//
//	line 1:  p0 event t=700  v=2 -> [0,1000) and [600,1600)
//	line 2:  p1 event t=1000 v=3 -> [600,1600)
//	line 3:  p2 event t=1300 v=5 -> [600,1600) and [1200,2200)
//	line 4:  p0 watermark 1600       (fast source races ahead)
//	line 5:  p1 watermark 1600
//	line 6:  p2 watermark 600        (laggard pins the effective minimum at 600)
//	line 7:  p2 watermark 1000       (effective advances to 1000: closes only [0,1000))
//	line 8:  p1 declares idle        (excluded from the minimum; effective stays 1000)
//	line 9:  p0 event t=999  v=9     (strictly below effective 1000: late, skipped whole)
//	line 10: p0 event t=1200 v=6     (1200 < p0's OWN watermark 1600, yet accepted:
//	                                  lateness uses the overall effective 1000, not the
//	                                  source's own watermark; joins [600,1600),[1200,2200))
//	line 11: p2 event t=1000 v=4     (equal to effective 1000: still counted; joins [600,1600))
//	line 12: p1 watermark 1600       (legal resume: >= old 1600 and >= effective 1000)
//	line 13: p2 watermark 1600       (effective = min(1600,1600,1600) = 1600: closes [600,1600))
//	line 14: p1 event t=1900 v=7     (resumed source participates again; -> [1200,2200) and [1800,2800))
//	line 15: p0 watermark 2200
//	line 16: p1 watermark 2200
//	line 17: p2 watermark 2200       (effective 2200: closes [1200,2200); [1800,2800) stays open)
func renumberFixtureSuccessLines() []string {
	return []string{
		`{"type":"event","key":"k","time":700,"value":2,"partition":0}`,
		`{"type":"event","key":"k","time":1000,"value":3,"partition":1}`,
		`{"type":"event","key":"k","time":1300,"value":5,"partition":2}`,
		`{"type":"watermark","time":1600,"partition":0}`,
		`{"type":"watermark","time":1600,"partition":1}`,
		`{"type":"watermark","time":600,"partition":2}`,
		`{"type":"watermark","time":1000,"partition":2}`,
		`{"type":"idle","partition":1}`,
		`{"type":"event","key":"k","time":999,"value":9,"partition":0}`,
		`{"type":"event","key":"k","time":1200,"value":6,"partition":0}`,
		`{"type":"event","key":"k","time":1000,"value":4,"partition":2}`,
		`{"type":"watermark","time":1600,"partition":1}`,
		`{"type":"watermark","time":1600,"partition":2}`,
		`{"type":"event","key":"k","time":1900,"value":7,"partition":1}`,
		`{"type":"watermark","time":2200,"partition":0}`,
		`{"type":"watermark","time":2200,"partition":1}`,
		`{"type":"watermark","time":2200,"partition":2}`,
	}
}

// Expected window accounting, independently re-checkable per source from the
// valid (non-late) events. The late t=999 event contributes nowhere.
//
//	[0,1000):   p0 {2}                            -> count 1, sum 2
//	[600,1600): p0 {2,6}=8, p1 {3}=3, p2 {5,4}=9  -> count 5, sum 20
//	[1200,2200): p0 {6}=6, p1 {7}=7, p2 {5}=5     -> count 3, sum 18
var renumberFixtureWantRows = []AggregateResult{
	{Key: "k", Start: 0, End: 1000, Count: 1, Sum: 2},
	{Key: "k", Start: 600, End: 1600, Count: 5, Sum: 20},
	{Key: "k", Start: 1200, End: 2200, Count: 3, Sum: 18},
}

const renumberFixtureWantStdout = `{"key":"k","start":0,"end":1000,"count":1,"sum":2}` + "\n" +
	`{"key":"k","start":600,"end":1600,"count":5,"sum":20}` + "\n" +
	`{"key":"k","start":1200,"end":2200,"count":3,"sum":18}` + "\n"

const renumberFixtureWantLate = "line 9: late event time=999 below current watermark 1000, skipped\n"

// acceptedSourceEvents lists every event the stream actually accepts (the
// late t=999 record is excluded), keyed by the ORIGINAL source number, so the
// expected per-window counts and sums can be recomputed from each source's
// valid events independently of the watermark/idle machinery and
// independently of the labels the run used.
var acceptedSourceEvents = []struct {
	source int64
	time   int64
	value  int64
}{
	{0, 700, 2},
	{1, 1000, 3},
	{2, 1300, 5},
	{0, 1200, 6},
	{2, 1000, 4},
	{1, 1900, 7},
}

// renumberWindowStarts are the windows closed by the final effective
// watermark 2200, enumerated directly (length 1000, left-closed right-open).
// [1800,2800) is intentionally absent: it stays open at end of input and must
// never be flushed.
var renumberWindowStarts = []int64{0, 600, 1200}

const renumberWindowLength int64 = 1000

// recomputeRowsBySource rebuilds the merged window rows from
// acceptedSourceEvents using plain interval containment (a different
// formulation than the engine's slide arithmetic), and additionally reports
// each source's own count/sum contribution per window start so the merged
// totals can be checked source by source.
func recomputeRowsBySource(t *testing.T) (map[int64]AggregateResult, map[int64]map[int64]struct{ count, sum int64 }) {
	t.Helper()
	rows := make(map[int64]AggregateResult)
	perSource := make(map[int64]map[int64]struct{ count, sum int64 })
	for _, start := range renumberWindowStarts {
		rows[start] = AggregateResult{Key: "k", Start: start, End: start + renumberWindowLength}
		perSource[start] = make(map[int64]struct{ count, sum int64 })
	}
	for _, ev := range acceptedSourceEvents {
		for _, start := range renumberWindowStarts {
			if ev.time >= start && ev.time < start+renumberWindowLength {
				r := rows[start]
				r.Count++
				r.Sum += ev.value
				rows[start] = r
				c := perSource[start][ev.source]
				c.count++
				c.sum += ev.value
				perSource[start][ev.source] = c
			}
		}
	}
	return rows, perSource
}

// TestSlidingPartitionRenumberingInvariantSuccess is the core guarantee:
// running the same business stream under the original labels and under the
// relabeling bijection produces exactly the same window output (content, row
// count and order) and the same late notices (event time, watermark and
// physical line number), and both runs succeed. The relabeling touches
// events, watermarks and idle declarations alike and never merges sources or
// leaves a record kind behind.
func TestSlidingPartitionRenumberingInvariantSuccess(t *testing.T) {
	original := renumberFixtureSuccessLines()
	relabeled := renumberPartitionFields(t, original, partitionRenumberPermutation)
	// Guard the guard: the relabeling really is a same-cardinality bijection
	// and really rewrote every partition-bearing record of every kind.
	assertPermutation(t, partitionRenumberPermutation, 3)
	assertEveryPartitionFieldMapped(t, original, relabeled, partitionRenumberPermutation)

	controlOut, controlLate, controlErr := runPartitionedSliding(t, strings.Join(original, "\n")+"\n", 1000, 600, 3)
	movedOut, movedLate, movedErr := runPartitionedSliding(t, strings.Join(relabeled, "\n")+"\n", 1000, 600, 3)

	if controlErr != nil {
		t.Fatalf("the control run must succeed: %v", controlErr)
	}
	if movedErr != nil {
		t.Fatalf("the relabeled run must succeed: %v", movedErr)
	}
	if controlOut != renumberFixtureWantStdout {
		t.Fatalf("control stdout mismatch:\n got: %q\nwant: %q", controlOut, renumberFixtureWantStdout)
	}
	if movedOut != controlOut {
		t.Fatalf("renumbering changed the window results:\n original: %q\nrelabeled: %q", controlOut, movedOut)
	}
	if controlLate != renumberFixtureWantLate {
		t.Fatalf("control late notice mismatch:\n got: %q\nwant: %q", controlLate, renumberFixtureWantLate)
	}
	if movedLate != controlLate {
		t.Fatalf("renumbering changed the late notice (event time/watermark/physical line must stay put):\n original: %q\nrelabeled: %q", controlLate, movedLate)
	}
	if strings.Contains(movedOut, "partition") {
		t.Errorf("the source number must never enter the output: %q", movedOut)
	}

	got := decodeAggregateResults(t, movedOut)
	if len(got) != len(renumberFixtureWantRows) {
		t.Fatalf("row count = %d, want %d", len(got), len(renumberFixtureWantRows))
	}
	for i := range renumberFixtureWantRows {
		if got[i] != renumberFixtureWantRows[i] {
			t.Errorf("row %d = %+v, want %+v", i, got[i], renumberFixtureWantRows[i])
		}
	}

	// Independently recompute every closed window from each source's valid
	// events; the merged rows and the per-source split must both reconcile.
	rows, perSource := recomputeRowsBySource(t)
	for _, start := range renumberWindowStarts {
		want := rows[start]
		var gotRow *AggregateResult
		for i := range got {
			if got[i].Start == start {
				gotRow = &got[i]
			}
		}
		if gotRow == nil {
			t.Errorf("window starting %d was not emitted", start)
			continue
		}
		if *gotRow != want {
			t.Errorf("window [%d,%d) = %+v, want %+v from per-source events", start, want.End, gotRow, want)
		}
		var sCount, sSum int64
		for _, c := range perSource[start] {
			sCount += c.count
			sSum += c.sum
		}
		if sCount != want.Count || sSum != want.Sum {
			t.Errorf("per-source contributions to [%d,%d) sum to count %d/sum %d, want %d/%d", start, want.End, sCount, sSum, want.Count, want.Sum)
		}
	}
	// The overlapping windows (slide 600 does not divide length 1000) are
	// where the same key's events from all three sources actually merge; the
	// early [0,1000) window legitimately holds only the fast source's event.
	for _, start := range []int64{600, 1200} {
		if len(perSource[start]) != 3 {
			t.Errorf("overlapping window starting %d should merge the same key's events from all 3 sources, got %d", start, len(perSource[start]))
		}
	}
}

// TestSlidingPartitionRenumberingResumeFailureBelowOwnOldWatermark keeps the
// branch where a sleeping source's resume watermark is below its OWN previous
// watermark. The failure must remain an *InputError on the same physical line
// (line 12) naming the actually violated bound ("previous watermark 1600"),
// while the number named for the source follows the relabeling (partition 1
// -> partition 0). Output already produced before the failure stays exactly
// as it was, and records after the failing line produce neither results nor
// late notices -- under either labeling.
func TestSlidingPartitionRenumberingResumeFailureBelowOwnOldWatermark(t *testing.T) {
	lines := renumberFixtureSuccessLines()[:11]
	lines = append(lines,
		`{"type":"watermark","time":900,"partition":1}`, // line 12: 900 < the source's own old 1600
		// Dead suffix: must never run after the fatal line 12.
		`{"type":"event","key":"k","time":998,"value":11,"partition":0}`, // line 13: would be late if reached
		`{"type":"watermark","time":1600,"partition":1}`,                 // line 14
		`{"type":"watermark","time":2200,"partition":0}`,                 // line 15
		`{"type":"watermark","time":2200,"partition":2}`,                 // line 16
	)
	cases := []struct {
		name       string
		recs       []string
		wantSource string
	}{
		{name: "original labels", recs: lines, wantSource: "partition 1"},
		{name: "relabeled 1->0", recs: renumberPartitionFields(t, lines, partitionRenumberPermutation), wantSource: "partition 0"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			out, late, err := runPartitionedSliding(t, strings.Join(tc.recs, "\n")+"\n", 1000, 600, 3)
			ie := inputErrorFrom(t, err)
			if ie.Line != 12 {
				t.Errorf("InputError.Line = %d, want 12 (same physical line under relabeling)", ie.Line)
			}
			for _, sub := range []string{
				"resume watermark 900",
				tc.wantSource,
				"previous watermark 1600",
			} {
				if !strings.Contains(ie.Reason, sub) {
					t.Errorf("reason %q must contain %q", ie.Reason, sub)
				}
			}
			if strings.Contains(ie.Reason, "effective watermark") {
				t.Errorf("the violated limit is the source's own previous watermark, not the effective one: %q", ie.Reason)
			}
			// Pre-failure output and the line-9 late notice stay; the dead
			// suffix adds neither a window row nor another notice.
			wantOut := `{"key":"k","start":0,"end":1000,"count":1,"sum":2}` + "\n"
			if out != wantOut {
				t.Errorf("stdout mismatch:\n got: %q\nwant: %q", out, wantOut)
			}
			if late != renumberFixtureWantLate {
				t.Errorf("late notices mismatch:\n got: %q\nwant: %q", late, renumberFixtureWantLate)
			}
		})
	}
}

// TestSlidingPartitionRenumberingResumeFailureBelowEffectiveWatermark keeps
// the other failure cause: a source that goes idle BEFORE ever reporting a
// watermark has no previous watermark of its own, so a resume watermark below
// the current OVERALL effective watermark is rejected citing that overall
// bound -- resume legality is never decided from one source's own watermark.
// The error again stays on the same physical line and names the relabeled
// source number.
func TestSlidingPartitionRenumberingResumeFailureBelowEffectiveWatermark(t *testing.T) {
	lines := []string{
		`{"type":"event","key":"k","time":100,"value":1,"partition":0}`, // line 1
		`{"type":"event","key":"k","time":200,"value":2,"partition":2}`, // line 2
		`{"type":"watermark","time":1000,"partition":0}`,                // line 3
		`{"type":"watermark","time":1000,"partition":2}`,                // line 4
		`{"type":"idle","partition":1}`,                                 // line 5: never-reported source idles
		`{"type":"watermark","time":2000,"partition":0}`,                // line 6
		`{"type":"watermark","time":2000,"partition":2}`,                // line 7: overall effective = 2000
		`{"type":"watermark","time":1500,"partition":1}`,                // line 8: 1500 < overall 2000
		// Dead suffix.
		`{"type":"event","key":"k","time":1900,"value":8,"partition":1}`, // line 9
		`{"type":"watermark","time":2000,"partition":1}`,                 // line 10
	}
	cases := []struct {
		name       string
		recs       []string
		wantSource string
	}{
		{name: "original labels", recs: lines, wantSource: "partition 1"},
		{name: "relabeled 1->0", recs: renumberPartitionFields(t, lines, partitionRenumberPermutation), wantSource: "partition 0"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			out, late, err := runPartitionedSliding(t, strings.Join(tc.recs, "\n")+"\n", 1000, 600, 3)
			ie := inputErrorFrom(t, err)
			if ie.Line != 8 {
				t.Errorf("InputError.Line = %d, want 8 (same physical line under relabeling)", ie.Line)
			}
			for _, sub := range []string{
				"resume watermark 1500",
				tc.wantSource,
				"current effective watermark 2000",
			} {
				if !strings.Contains(ie.Reason, sub) {
					t.Errorf("reason %q must contain %q", ie.Reason, sub)
				}
			}
			if strings.Contains(ie.Reason, "previous watermark") {
				t.Errorf("a never-reported source has no previous watermark to cite: %q", ie.Reason)
			}
			wantOut := `{"key":"k","start":0,"end":1000,"count":2,"sum":3}` + "\n"
			if out != wantOut {
				t.Errorf("stdout mismatch:\n got: %q\nwant: %q", out, wantOut)
			}
			if late != "" {
				t.Errorf("a rejected resume produces no late notice, got %q", late)
			}
		})
	}
}

// TestSlidingPartitionRenumberingPermutationIsABijection pins the labeling
// constraint itself: the relabeling must be a one-to-one correspondence onto
// {0,1,2}, stay in range and keep using the zero and the maximum legal index,
// so sources can never be merged or dropped.
func TestSlidingPartitionRenumberingPermutationIsABijection(t *testing.T) {
	if !isPermutation(partitionRenumberPermutation, 3) {
		t.Fatalf("the renumbering under test must be a bijection: %v", partitionRenumberPermutation)
	}
	// Maps that merge sources, drop a source, leave the range or keep a
	// boundary role fixed must all be rejected by the same predicate.
	for name, bad := range map[string]map[int64]int64{
		"two sources merge into one": {0: 0, 1: 0, 2: 1},
		"a source is dropped":        {0: 2, 1: 0},
		"target out of range":        {0: 2, 1: 3, 2: 1},
		"zero role never moves":      {0: 0, 1: 2, 2: 1},
		"max role never moves":       {0: 1, 1: 0, 2: 2},
	} {
		if isPermutation(bad, 3) {
			t.Errorf("%s must not be accepted as a renumbering bijection: %v", name, bad)
		}
	}
}

// isPermutation reports whether m is a bijection of {0,...,n-1} onto itself:
// every source is covered and maps to a distinct in-range target, the zero and
// maximum legal indices are both reused, and neither boundary role keeps its
// original number (so the safeguard genuinely moves the boundary roles).
func isPermutation(m map[int64]int64, n int64) bool {
	if int64(len(m)) != n {
		return false
	}
	seen := make(map[int64]bool)
	for old, next := range m {
		if old < 0 || old >= n || next < 0 || next >= n {
			return false
		}
		if seen[next] {
			return false
		}
		seen[next] = true
	}
	if !seen[0] || !seen[n-1] {
		return false
	}
	if m[0] == 0 || m[n-1] == n-1 {
		return false
	}
	return true
}

// assertPermutation fails the test unless m is a renumbering bijection.
func assertPermutation(t *testing.T, m map[int64]int64, n int64) {
	t.Helper()
	if !isPermutation(m, n) {
		t.Fatalf("renumbering %v is not a bijection of [0,%d) onto itself", m, n)
	}
}

// assertEveryPartitionFieldMapped compares two physical input streams that
// differ only in partition labels: every record keeps its type and line
// position, and each partition-bearing record (event, watermark and idle
// alike) carries exactly f(original). This proves no record kind was missed
// and no source was merged or relabeled inconsistently.
func assertEveryPartitionFieldMapped(t *testing.T, original, relabeled []string, f map[int64]int64) {
	t.Helper()
	if len(original) != len(relabeled) {
		t.Fatalf("renumbering changed the record count: %d -> %d", len(original), len(relabeled))
	}
	kinds := map[string]int{}
	for i, before := range original {
		var o, rl map[string]json.RawMessage
		if err := json.Unmarshal([]byte(before), &o); err != nil {
			t.Fatalf("original line %d is not JSON: %v", i+1, err)
		}
		if err := json.Unmarshal([]byte(relabeled[i]), &rl); err != nil {
			t.Fatalf("relabeled line %d is not JSON: %v", i+1, err)
		}
		if string(o["type"]) != string(rl["type"]) {
			t.Errorf("line %d record type changed: %s -> %s", i+1, o["type"], rl["type"])
		}
		raw, ok := o["partition"]
		if !ok {
			t.Errorf("line %d (%s) carries no partition field to relabel", i+1, o["type"])
			continue
		}
		var oldP int64
		if err := json.Unmarshal(raw, &oldP); err != nil {
			t.Fatalf("line %d partition is not an integer: %v", i+1, err)
		}
		var newP int64
		if err := json.Unmarshal(rl["partition"], &newP); err != nil {
			t.Fatalf("line %d relabeled partition is not an integer: %v", i+1, err)
		}
		if newP != f[oldP] {
			t.Errorf("line %d (%s): partition %d relabeled to %d, want %d", i+1, o["type"], oldP, newP, f[oldP])
		}
		kinds[string(o["type"])]++
	}
	for _, kind := range []string{`"event"`, `"watermark"`, `"idle"`} {
		if kinds[kind] == 0 {
			t.Errorf("the stream must include %s records so that kind cannot be skipped by renumbering", kind)
		}
	}
}

// renumberPartitionFields returns the physical records with every record's
// partition field replaced by f(its old value). It rewrites events,
// watermarks and idle declarations with the single correspondence and leaves
// record order and all other fields untouched. Re-marshaling changes only
// formatting, never decoded content, so the engine sees an identical stream
// apart from source labels.
func renumberPartitionFields(t *testing.T, records []string, f map[int64]int64) []string {
	t.Helper()
	out := make([]string, len(records))
	for i, line := range records {
		var obj map[string]json.RawMessage
		if err := json.Unmarshal([]byte(line), &obj); err != nil {
			t.Fatalf("line %d is not JSON: %v", i+1, err)
		}
		raw, ok := obj["partition"]
		if !ok {
			t.Fatalf("line %d has no partition field to renumber: %s", i+1, line)
		}
		var p int64
		if err := json.Unmarshal(raw, &p); err != nil {
			t.Fatalf("line %d partition is not an integer: %v", i+1, err)
		}
		next, ok := f[p]
		if !ok {
			t.Fatalf("line %d: no renumbering target for source %d", i+1, p)
		}
		obj["partition"] = json.RawMessage(fmt.Sprintf("%d", next))
		b, err := json.Marshal(obj)
		if err != nil {
			t.Fatalf("line %d could not be re-marshaled: %v", i+1, err)
		}
		out[i] = string(b)
	}
	return out
}

package edgefleet

import (
	"strconv"
	"strings"
	"testing"
)

// Regression safeguards for the interaction between idle declarations and the
// effective (minimum) watermark when several active partitions tie on the
// minimum in partitioned sliding mode (window 1000, slide 600, three
// partitions, one key "k"):
//
//   - With the per-partition watermarks 1600/600/600 the effective watermark
//     is 600 and no window has closed. Declaring ONE of the two slow
//     partitions idle must not advance the effective watermark: the other,
//     still-active partition still pins it at 600, so no window may close
//     early. Only when that last holder of the minimum declares idle does the
//     remaining partition's 1600 become the effective watermark and close the
//     windows.
//   - While one minimum holder is idle, a legal event arriving from the other,
//     still-active minimum holder (time 1000, equal to the would-be window
//     edge and well above the effective 600) is judged against the effective
//     watermark 600 -- never against the fast partition's own 1600 -- so it is
//     neither reported late nor dropped; it joins the still-open overlapping
//     window.
//   - The window that closes last keeps the events both partitions
//     contributed before they went idle. The event at 1300 also belongs to
//     [1200,2200), which stays open at end of input and is never flushed.
//   - The rule is symmetric in which of the two tied partitions idles first,
//     and a repeated idle declaration for an already-idle partition is a
//     no-op: it neither advances the watermark nor re-emits any result while
//     the other slow partition stays active.
//
// Every check goes through the public RunAggregatePartitionedSliding entry
// point; output stays the existing line-per-JSON format with no partition
// field, and the normal path produces neither late notices nor errors.

// tiedMinIdleBaseLines is the shared history physical lines 1-6:
//
//	line 1: p0 event time=700  value=2 -> [0,1000) and [600,1600)
//	line 2: p1 event time=1000 value=3 -> [600,1600)
//	line 3: p2 event time=1300 value=5 -> [600,1600) and [1200,2200)
//	line 4: p0 watermark 1600           -> fast partition races ahead
//	line 5: p1 watermark 600
//	line 6: p2 watermark 600            -> effective min = 600; nothing closes
//
// Windows in play start at 0, 600, 1200, ... with length 1000.
func tiedMinIdleBaseLines() []string {
	return []string{
		`{"type":"event","key":"k","time":700,"value":2,"partition":0}`,
		`{"type":"event","key":"k","time":1000,"value":3,"partition":1}`,
		`{"type":"event","key":"k","time":1300,"value":5,"partition":2}`,
		`{"type":"watermark","time":1600,"partition":0}`,
		`{"type":"watermark","time":600,"partition":1}`,
		`{"type":"watermark","time":600,"partition":2}`,
	}
}

// tiedMinIdleWantOutput is the exact, order-pinned output the full sequence
// must produce, with no partition field:
//
//   - [0,1000) holds only partition 0's time=700 event (the time=1000 events
//     sit on the right edge and must not leak back): count 1, sum 2.
//   - [600,1600) keeps both idle partitions' pre-idle contributions (2 from
//     p0, 3 from p1, 5 from p2) plus the still-active holder's legal event
//     after the first idle declaration (4): count 4, sum 14.
//
// [1200,2200) (holding the time=1300 event, count 1, sum 5) is not among the
// rows: it is still open when input ends.
var tiedMinIdleWantOutput = strings.Join([]string{
	`{"key":"k","start":0,"end":1000,"count":1,"sum":2}`,
	`{"key":"k","start":600,"end":1600,"count":4,"sum":14}`,
	``,
}, "\n")

// TestSlidingPartitionTiedMinWatermarkNoClosureBeforeLastHolderIdles pins the
// output timing: after the three watermarks establish 600 as the effective
// minimum, neither that state nor the first idle declaration (nor repeated
// declarations of the same already-idle partition) may close any window,
// because the other slow partition is still active at 600. A legal event from
// that still-active partition after the first idle declaration is accepted
// with no late notice even though partition 0's own watermark is 1600.
func TestSlidingPartitionTiedMinWatermarkNoClosureBeforeLastHolderIdles(t *testing.T) {
	cases := []struct {
		name      string
		firstIdle int64 // the slow partition that declares idle first (1 or 2)
		active    int64 // the other slow partition, still active at 600
	}{
		{name: "partition 1 idles first, partition 2 holds the minimum", firstIdle: 1, active: 2},
		{name: "partition 2 idles first, partition 1 holds the minimum", firstIdle: 2, active: 1},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			lines := tiedMinIdleBaseLines()
			lines = append(lines,
				`{"type":"idle","partition":`+pid(tc.firstIdle)+`}`,
				// Repeating the already-idle declaration must stay a no-op.
				`{"type":"idle","partition":`+pid(tc.firstIdle)+`}`,
				`{"type":"idle","partition":`+pid(tc.firstIdle)+`}`,
				// time 1000 >= effective 600: legal, joins [600,1600), closes
				// nothing. It must not be judged late against p0's own 1600.
				`{"type":"event","key":"k","time":1000,"value":4,"partition":`+pid(tc.active)+`}`,
			)
			stdout, stderr, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 3)
			if err != nil {
				t.Fatalf("unexpected error while the last minimum holder stays active: %v", err)
			}
			if stderr != "" {
				t.Errorf("the active holder's time=1000 event must not be late vs effective 600, got notice %q", stderr)
			}
			if stdout != "" {
				t.Errorf("no window may close while active partition %d still pins the effective watermark at 600, got output %q", tc.active, stdout)
			}
		})
	}
}

// TestSlidingPartitionTiedMinWatermarkIdleSequence is the primary scenario:
// once the second (last active) holder of the minimum declares idle,
// partition 0's 1600 becomes the effective watermark and closes [0,1000) and
// [600,1600) in that order with the merged counts and sums, preserving the
// events both partitions contributed before idling. [1200,2200) stays open at
// end of input. The whole run produces no late notice and no error.
func TestSlidingPartitionTiedMinWatermarkIdleSequence(t *testing.T) {
	lines := tiedMinIdleBaseLines()
	lines = append(lines,
		`{"type":"idle","partition":1}`,                                  // p1 leaves; p2 still active at 600
		`{"type":"event","key":"k","time":1000,"value":4,"partition":2}`, // legal: joins [600,1600)
		`{"type":"idle","partition":2}`,                                  // last minimum holder leaves: effective = 1600
	)
	stdout, stderr, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 3)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if stderr != "" {
		t.Fatalf("normal processing must produce no late notice, got %q", stderr)
	}
	if stdout != tiedMinIdleWantOutput {
		t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, tiedMinIdleWantOutput)
	}

	// Pin the exact rows as structured values, and make sure the still-open
	// [1200,2200) window (which holds the time=1300 event) is never emitted.
	got := decodeAggregateResults(t, stdout)
	wantRows := []AggregateResult{
		{Key: "k", Start: 0, End: 1000, Count: 1, Sum: 2},
		{Key: "k", Start: 600, End: 1600, Count: 4, Sum: 14},
	}
	if len(got) != len(wantRows) {
		t.Fatalf("got %d rows, want %d (no [1200,2200) flush at end of input): %v", len(got), len(wantRows), got)
	}
	for i := range wantRows {
		if got[i] != wantRows[i] {
			t.Errorf("row %d = %+v, want %+v", i, got[i], wantRows[i])
		}
	}
}

// TestSlidingPartitionTiedMinWatermarkIdleOrderSymmetric proves both holders
// of the tied minimum obey the same rule regardless of which one declares
// idle first: the legal event after the first declaration is sent by the
// partition that remains active, and the second declaration is what finally
// lets partition 0's 1600 close the windows. Both orderings yield the same two
// result lines, no other output, and no late notices.
func TestSlidingPartitionTiedMinWatermarkIdleOrderSymmetric(t *testing.T) {
	cases := []struct {
		name       string
		firstIdle  int64
		secondIdle int64
		active     int64 // sends the legal time=1000 event between the two declarations
	}{
		{name: "p1 idles then active p2 contributes then idles", firstIdle: 1, secondIdle: 2, active: 2},
		{name: "p2 idles then active p1 contributes then idles", firstIdle: 2, secondIdle: 1, active: 1},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			lines := tiedMinIdleBaseLines()
			lines = append(lines,
				`{"type":"idle","partition":`+pid(tc.firstIdle)+`}`,
				`{"type":"event","key":"k","time":1000,"value":4,"partition":`+pid(tc.active)+`}`,
				`{"type":"idle","partition":`+pid(tc.secondIdle)+`}`,
			)
			stdout, stderr, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 3)
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if stderr != "" {
				t.Fatalf("normal processing must produce no late notice, got %q", stderr)
			}
			if stdout != tiedMinIdleWantOutput {
				t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, tiedMinIdleWantOutput)
			}
		})
	}
}

// TestSlidingPartitionTiedMinRepeatedIdleNeverAdvancesWatermark combines the
// no-op guarantee with the timing guarantee: after partition 1 idles, further
// idle declarations for the same already-idle partition 1 must neither close
// windows nor duplicate results while partition 2 still holds the minimum at
// 600. The active holder's time=1000 event still aggregates normally, and the
// single later idle declaration for partition 2 is the one record that closes
// the windows -- exactly once each.
func TestSlidingPartitionTiedMinRepeatedIdleNeverAdvancesWatermark(t *testing.T) {
	lines := tiedMinIdleBaseLines()
	lines = append(lines,
		`{"type":"idle","partition":1}`,
		`{"type":"idle","partition":1}`, // repeated: still-active p2 keeps effective 600
		`{"type":"idle","partition":1}`, // repeated again: same no-op
		`{"type":"event","key":"k","time":1000,"value":4,"partition":2}`,
		`{"type":"idle","partition":2}`, // last minimum holder leaves: closes both windows
		`{"type":"idle","partition":2}`, // repeated after closure: must not re-emit
	)
	stdout, stderr, err := runPartitionedSliding(t, strings.Join(lines, "\n"), 1000, 600, 3)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if stderr != "" {
		t.Fatalf("normal processing must produce no late notice, got %q", stderr)
	}
	if stdout != tiedMinIdleWantOutput {
		t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, tiedMinIdleWantOutput)
	}
	// Each window appears exactly once: a repeated idle declaration must never
	// add or duplicate a result line.
	if n := strings.Count(stdout, `"start":0,"end":1000`); n != 1 {
		t.Errorf("[0,1000) emitted %d times, want exactly 1", n)
	}
	if n := strings.Count(stdout, `"start":600,"end":1600`); n != 1 {
		t.Errorf("[600,1600) emitted %d times, want exactly 1", n)
	}
	if strings.Contains(stdout, `"start":1200`) {
		t.Errorf("[1200,2200) is still open at end of input and must never be emitted: %q", stdout)
	}
}

// pid formats a partition index for embedding in a JSON record.
func pid(p int64) string {
	return strconv.FormatInt(p, 10)
}

// Command edgefleet is the 验证者与边缘节点机群管理平台 entry point.
package main

import (
	"errors"
	"flag"
	"fmt"
	"os"

	"github.com/asdhoaiqqq/edgefleet-validator/edgefleet"
)

func main() {
	command := "demo"
	if len(os.Args) > 1 {
		command = os.Args[1]
	}
	switch command {
	case "demo":
		runDemo()
	case "version":
		fmt.Println("edgefleet 0.1.0")
	case "aggregate":
		os.Exit(runAggregate(os.Args[2:]))
	case "help", "-h", "--help":
		usage()
	default:
		fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
		usage()
		os.Exit(2)
	}
}

func usage() {
	fmt.Println("usage: edgefleet [demo|version|aggregate --window-ms <milliseconds> [--slide-ms <milliseconds>] [--partitions <count>]|help]")
	fmt.Println()
	fmt.Println("commands:")
	fmt.Println("  demo       run a built-in fleet health demonstration")
	fmt.Println("  version    print the edgefleet version")
	fmt.Println("  aggregate  aggregate JSON events from standard input into fixed or sliding windows")
	fmt.Println("  help       show this help")
	fmt.Println()
	fmt.Println("aggregate:")
	fmt.Println("  edgefleet aggregate --window-ms <milliseconds> [--slide-ms <milliseconds>] [--partitions <count>]")
	fmt.Println()
	fmt.Println("  --window-ms is a required positive signed 64-bit integer. Aggregation runs")
	fmt.Println("  fully offline and never uses the current time; all timing comes from input.")
	fmt.Println()
	fmt.Println("  standard input is line-delimited JSON with two record types:")
	fmt.Println(`    {"type":"event","key":"sensor-a","time":1200,"value":5}`)
	fmt.Println(`    {"type":"watermark","time":2000}`)
	fmt.Println("  time is a non-negative signed 64-bit millisecond timestamp, value is a")
	fmt.Println("  signed 64-bit integer, and key is a non-empty string. Blank lines are")
	fmt.Println("  ignored, but error line numbers count every physical input line.")
	fmt.Println()
	fmt.Println("  windows start at time zero, have the fixed length given by --window-ms")
	fmt.Println("  and are left-closed, right-open: [start,end). Every valid event for a key")
	fmt.Println("  in a window contributes to its count and sum; windows with no events do")
	fmt.Println("  not produce output. Records may arrive out of order; window membership")
	fmt.Println("  uses event time only.")
	fmt.Println()
	fmt.Println("  --slide-ms makes the windows overlap: it gives the positive signed")
	fmt.Println("  64-bit integer distance between consecutive window starts (0, one")
	fmt.Println("  interval, two intervals, ...), must not exceed --window-ms and does not")
	fmt.Println("  have to divide it. Each valid event counts once in every window that")
	fmt.Println("  contains its event time, adding its value in full to each of them; for")
	fmt.Println("  example length 1000 with interval 600 produces [0,1000), [600,1600),")
	fmt.Println("  [1200,2200), ... and an event at time 1000 is outside the first. When")
	fmt.Println("  --slide-ms is omitted or equals --window-ms the behavior is identical")
	fmt.Println("  to fixed windows.")
	fmt.Println()
	fmt.Println("  a watermark declares that events with time below it are late. Before the")
	fmt.Println("  first watermark every valid event is accepted. After a watermark, every")
	fmt.Println("  window whose end is less than or equal to the watermark is closed once")
	fmt.Println("  and emitted as one JSON line with key,start,end,count,sum; the sum is a")
	fmt.Println("  signed 64-bit integer. Closures are ordered by end ascending and then by")
	fmt.Println("  key in UTF-8 byte order. Watermarks may jump or repeat, and an event at")
	fmt.Println("  exactly the current watermark is still valid; events below the current")
	fmt.Println("  watermark are skipped with a note on standard error, even when they")
	fmt.Println("  would still fall inside an unclosed overlapping window. Still-open")
	fmt.Println("  windows are never emitted at end of input.")
	fmt.Println()
	fmt.Println("  --partitions merges several independent input sources of the same stream.")
	fmt.Println("  <count> must be a positive signed 64-bit integer. When it is given, every")
	fmt.Println("  event and watermark record must additionally carry an integer partition in")
	fmt.Println("  [0,count):")
	fmt.Println(`    {"type":"event","key":"sensor-a","time":1200,"value":5,"partition":0}`)
	fmt.Println(`    {"type":"watermark","time":2000,"partition":0}`)
	fmt.Println(`    {"type":"idle","partition":0}`)
	fmt.Println("  each partition advances its own watermark independently. No effective")
	fmt.Println("  watermark exists until every partition has reported at least once;")
	fmt.Println("  afterwards the effective watermark is the minimum of the per-partition")
	fmt.Println("  values, and window closure and late-event checks use that minimum, so one")
	fmt.Println("  partition's larger watermark can never close a window or drop an event")
	fmt.Println("  ahead of the others. A partition watermark may repeat or jump forward but")
	fmt.Println("  never move backwards. Events from different partitions for the same key")
	fmt.Println("  and window merge into one count and sum; output records never include a")
	fmt.Println("  partition field. Sliding windows combine with partitions: the same key")
	fmt.Println("  from different partitions merges within each overlapping window, and the")
	fmt.Println("  effective watermark alone drives late-event checks and closure. Without")
	fmt.Println("  --partitions the command keeps the single watermark behavior and ignores")
	fmt.Println("  extra fields.")
	fmt.Println()
	fmt.Println("  an idle record declares a partition temporarily without data. It is")
	fmt.Println("  declared by the input only and is never inferred from the current time")
	fmt.Println("  or read gaps. From that record on the partition is excluded from the")
	fmt.Println("  effective watermark, so it no longer holds the others back; the idle")
	fmt.Println("  record itself may close windows. A non-idle partition that has not")
	fmt.Println("  reported yet still keeps the effective watermark unknown; when every")
	fmt.Println("  partition is idle the last produced effective watermark is retained")
	fmt.Println("  (and stays unknown if none was produced). Idleness is not an infinite")
	fmt.Println("  watermark and does not drop pending events. Repeating an idle record")
	fmt.Println("  for the same partition succeeds without extra output. A partition")
	fmt.Println("  resumes on its next watermark record: its time must be at least both")
	fmt.Println("  its own previous watermark and the current effective watermark. An")
	fmt.Println("  event arriving while the partition is idle is fatal; it neither")
	fmt.Println("  resumes the partition nor is silently treated as late. In single")
	fmt.Println("  watermark mode an idle record is an unknown record type.")
	fmt.Println()
	fmt.Println("  invalid command parameters -- a missing --window-ms, or a")
	fmt.Println("  non-positive --window-ms or --slide-ms, or a --slide-ms larger than")
	fmt.Println("  --window-ms, or a non-positive --partitions -- print the reason to")
	fmt.Println("  standard error and exit non-zero before any input is read. Malformed")
	fmt.Println("  JSON, missing or mistyped fields, out-of-range integers, unknown")
	fmt.Println("  record types, missing or out-of-range partitions, partition watermark")
	fmt.Println("  regression, an event for an idle partition, a resume watermark below")
	fmt.Println("  the partition's previous or the effective watermark, an event key")
	fmt.Println("  whose character encoding or Unicode escape is damaged (invalid UTF-8")
	fmt.Println("  bytes, or an unpaired or mispaired surrogate), and window-end,")
	fmt.Println("  event-count or cumulative-sum overflow print the input line number and")
	fmt.Println("  reason to standard error and stop processing with a non-zero exit; no")
	fmt.Println("  further records are read and earlier output is retained. A window")
	fmt.Println("  result or late-event notice that cannot be written in full (the")
	fmt.Println("  output writer errors, even after accepting a prefix, or accepts too")
	fmt.Println("  few bytes without an error) is likewise fatal with the triggering")
	fmt.Println("  input line number, the affected key and window or the skipped event")
	fmt.Println("  time and watermark, and the writer's error; the failed content is not")
	fmt.Println("  resent, no further windows are emitted and content already written is")
	fmt.Println("  retained. Standard output contains window results only. A failure while")
	fmt.Println("  reading standard input is likewise fatal: records whose newline was")
	fmt.Println("  received, including those carried by the failing read, are processed in")
	fmt.Println("  order first, but the unterminated trailing bytes never become a record,")
	fmt.Println("  and the reader's error is reported here with a non-zero exit; clean end")
	fmt.Println("  of input is not a read failure, so a final record without a trailing")
	fmt.Println("  newline is still processed.")
}

func runAggregate(args []string) int {
	fs := flag.NewFlagSet("aggregate", flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	fs.Usage = func() {
		fmt.Fprintln(fs.Output(), "usage: edgefleet aggregate --window-ms <milliseconds> [--slide-ms <milliseconds>] [--partitions <count>]")
		fmt.Fprintln(fs.Output(), `run "edgefleet help" for the full record and window closure rules`)
	}
	windowMillis := fs.Int64("window-ms", 0, "window length in milliseconds (required, positive signed 64-bit integer)")
	slideMillis := fs.Int64("slide-ms", 0, "distance between consecutive window starts in milliseconds (optional positive signed 64-bit integer, no greater than --window-ms); defaults to the window length for non-overlapping fixed windows")
	partitions := fs.Int64("partitions", 0, "number of input partitions (optional positive signed 64-bit integer); when set, every record must carry an integer partition in [0,count)")
	if err := fs.Parse(args); err != nil {
		return 2
	}
	if fs.NArg() != 0 {
		fmt.Fprintf(os.Stderr, "aggregate accepts no positional arguments, got %v\n", fs.Args())
		fs.Usage()
		return 2
	}
	windowSpecified := false
	slideSpecified := false
	partitionsSpecified := false
	fs.Visit(func(f *flag.Flag) {
		switch f.Name {
		case "window-ms":
			windowSpecified = true
		case "slide-ms":
			slideSpecified = true
		case "partitions":
			partitionsSpecified = true
		}
	})
	if !windowSpecified {
		fmt.Fprintln(os.Stderr, "aggregate requires --window-ms <milliseconds>")
		fs.Usage()
		return 2
	}
	// An omitted --slide-ms defaults to the window length (fixed windows).
	// This is an omission policy specific to the command: an explicitly given
	// zero is left untouched, so it is still rejected below rather than being
	// silently treated as the default.
	if !slideSpecified {
		*slideMillis = *windowMillis
	}
	// The numeric limits are shared with the library entry points and live in
	// edgefleet.ValidateAggregateParams; only the flag-named wording and exit
	// code are command-specific. The shared report order (window, slide,
	// slide-vs-window, partitions) is the order this command already used.
	if err := edgefleet.ValidateAggregateParams(*windowMillis, *slideMillis, *partitions); err != nil {
		var paramErr *edgefleet.AggregateParamError
		if errors.As(err, &paramErr) {
			fmt.Fprint(os.Stderr, aggregateParamCLIError(paramErr))
		} else {
			fmt.Fprintln(os.Stderr, "aggregate:", err)
		}
		return 2
	}
	// The command rejects an explicitly supplied non-positive --partitions;
	// the library accepts zero as its legacy single-watermark mode selector.
	// The shared validator already rejected negative counts, so here this only
	// catches an explicit zero, kept as the command's own policy.
	if partitionsSpecified && *partitions <= 0 {
		fmt.Fprintf(os.Stderr, "aggregate --partitions must be a positive signed 64-bit integer, got %d\n", *partitions)
		return 2
	}
	var err error
	if partitionsSpecified {
		err = edgefleet.RunAggregatePartitionedSliding(os.Stdin, *windowMillis, *slideMillis, *partitions, os.Stdout, os.Stderr)
	} else {
		err = edgefleet.RunAggregateSliding(os.Stdin, *windowMillis, *slideMillis, os.Stdout, os.Stderr)
	}
	if err != nil {
		fmt.Fprintln(os.Stderr, "aggregate:", err)
		return 1
	}
	return 0
}

// aggregateParamCLIError renders a shared *edgefleet.AggregateParamError in
// the command's existing flag-named wording. The limit and its checking order
// come from edgefleet.ValidateAggregateParams; only this text and the exit
// code are command-specific.
func aggregateParamCLIError(e *edgefleet.AggregateParamError) string {
	switch e.Kind {
	case edgefleet.AggregateParamTooLarge:
		return fmt.Sprintf("aggregate --slide-ms %d must not exceed --window-ms %d\n", e.Value, e.Limit)
	case edgefleet.AggregateParamNotPositive:
		switch e.Field {
		case edgefleet.AggregateParamWindow:
			return fmt.Sprintf("aggregate --window-ms must be a positive signed 64-bit integer, got %d\n", e.Value)
		case edgefleet.AggregateParamSlide:
			return fmt.Sprintf("aggregate --slide-ms must be a positive signed 64-bit integer, got %d\n", e.Value)
		case edgefleet.AggregateParamPartitions:
			return fmt.Sprintf("aggregate --partitions must be a positive signed 64-bit integer, got %d\n", e.Value)
		}
	}
	return fmt.Sprintf("aggregate: invalid %s parameter %d\n", e.Field, e.Value)
}

func runDemo() {
	nodes := []edgefleet.Node{
		{ID: "val-eu-1", Region: "eu", Version: "1.26.0", Online: true},
		{ID: "val-us-1", Region: "us", Version: "1.25.4", Online: true, Missed: 3},
		{ID: "edge-ap-1", Region: "ap", Version: "1.26.0", Online: false},
	}
	unhealthy := 0
	for _, node := range nodes {
		health := edgefleet.Evaluate(node, "1.26.0", 1)
		if !health.Healthy {
			unhealthy++
		}
		fmt.Printf("node=%s healthy=%v findings=%v\n", health.Node, health.Healthy, health.Findings)
	}
	fmt.Println("rollout order:", edgefleet.Plan(nodes, "1.26.0"))
	fmt.Printf("summary: %d of %d nodes need attention\n", unhealthy, len(nodes))
}

