package oldref_test

import (
	"bytes"
	"fmt"
	"math/rand"
	"strings"
	"testing"

	"github.com/asdhoaiqqq/edgefleet-validator/edgefleet"
	"github.com/asdhoaiqqq/edgefleet-validator/edgefleet_oldref_check"
)

// Differential check: thousands of random partitioned streams (fixed and
// sliding windows) must produce byte-identical window output, late notices
// and the same nil/typed error from the refactored engine and the engine at
// HEAD. The generators deliberately include watermark regressions, idle
// declarations on never-reported partitions, resumes above and below the
// bounds, and events on idle partitions, so the error paths are compared too.

func runOne(fn func(r interface {
	Read(p []byte) (int, error)
}, windowMillis, slideMillis, partitions int64, out, late interface {
	Write(p []byte) (int, error)
}) error) {
}

func genRecords(rng *rand.Rand, partitions int64) []string {
